<?phpif (!defined('BASEPATH'))    exit('No direct script access allowed');class mportmodel extends CI_Model {    function fnGetPortInfo($VarPort = '', $VarCity = '', $VarCountry = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('pn.id,portname,portcity,portcountry,countryname,updatedby,pn.status,pn.dateupdated');        $this->db->from(KN_MASTER_PORT . " AS pn");        // if ($VarStatus <> '') {        //     $this->db->where_in('pn.status', array($VarStatus));        // } else {        //     $this->db->where_in('pn.status', array(1, 2));        // }        $this->db->join(KN_COUNTRIES . " AS c", 'pn.portcountry = c.id');        if ($VarId <> '') {            $ArrWhere['pn.id'] = $VarId;        }        if ($VarPort <> '') {            $ArrWhere['portname'] = trim($VarPort);        }        // if ($VarCity <> '') {        //     $ArrWhere['portcity'] = $VarCity;        // }        // if ($VarCountry <> '') {        //     $ArrWhere['portcountry'] = $VarCountry;        // }        if ($VarCompanyId <> '') {            $ArrWhere['pn.companyid'] = $VarCompanyId;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckPort($VarPort = '', $VarCity = '', $VarCountry = '', $VarId = '', $VarCompanyId = '') {        $this->db->from(KN_MASTER_PORT);       // $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarPort <> '') {            $ArrWhere['portname'] = trim($VarPort);        }        // if ($VarCity <> '') {        //     $ArrWhere['portcity'] = $VarCity;        // }        // if ($VarCountry <> '') {        //     $ArrWhere['portcountry'] = $VarCountry;        // }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        // echo $this->db->where($ArrWhere)->get_compiled_select();        // die;        return $this->db->where($ArrWhere)->count_all_results();    }    function savePortInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetPortInfo($ArrUpdateData['portname'], $ArrUpdateData['portcity'], $ArrUpdateData['portcountry'], 1, '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_PORT, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This port already exists";            }        } else {            $ArrCheckExist = $this->fnCheckPort($ArrUpdateData['portname'], $ArrUpdateData['portcity'], $ArrUpdateData['portcountry'], $VarId, $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_PORT, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This port already exists";            }        }        return $ArrResult;    }    function fnCountPort($VarPortName = '', $VarPortCity = '', $VarPortCountry = '', $VarStatus = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarPortName <> '') {            $ArrWhere[] = "pn.portname like '%" . $VarPortName . "%'";        }        if ($VarPortCity <> '') {            $ArrWhere[] = "pn.portcity like '%" . $VarPortCity . "%'";        }        if ($VarPortCountry <> '') {            $ArrWhere[] = "portcountry = '" . $VarPortCountry . "'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = " . $ArrUserLoggedInfo['companyid'];        }        $VarSqlPort = "SELECT count(1) as trec  FROM " . KN_MASTER_PORT . " AS pn         LEFT JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id LEFT JOIN " . KN_COUNTRIES . " AS c ON pn.portcountry = c.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlPort)->row();        return $ObjRows->trec;    }    function fnListPort($VarPortName = '', $VarPortCity = '', $VarPortCountry = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('portname', 'portcity', 'countryname', 'pn.status', 'contactname', 'pn.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'pn.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarPortName <> '') {            $ArrWhere[] = "pn.portname like '%" . $VarPortName . "%'";        }        if ($VarPortCity <> '') {            $ArrWhere[] = "pn.portcity like '%" . $VarPortCity . "%'";        }        if ($VarPortCountry <> '') {            $ArrWhere[] = "portcountry = '" . $VarPortCountry . "'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status = " . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = " . $ArrUserLoggedInfo['companyid'];        }       // removed this line in . " limit " . $VarLimitInfo  below query        $VarSqlPort = "SELECT pn.id,pn.portname,u.contactname,pn.dateupdated,pn.status,pn.portcity,countryname FROM " . KN_MASTER_PORT . " AS pn LEFT JOIN " . KN_USERS . " AS u         ON pn.updatedby = u.id LEFT JOIN " . KN_COUNTRIES . " AS c ON pn.portcountry = c.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder;        $ObjResult = $this->db->query($VarSqlPort);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_PORT, array('status' => $optvalue))) {            return true;        }        return false;    }}